export const TYPES={rack:['Стойка','▥'],server:['Сервер','▤'],proxmox:['Proxmox VE','◈'],vm:['Виртуальная машина','▣'],ubuntu:['Ubuntu','◉'],debian:['Debian','◉'],windows:['Windows Server','⊞'],containerd:['containerd','⬡'],kubelet:['kubelet','⚙'],docker:['Docker Engine','⬡'],container:['Docker контейнер','◇'],application:['Приложение','▧'],k8s_service:['Kubernetes Service','⇢'],k8s_cluster:['Кластер Kubernetes','⎈'],proxmox_cluster:['Кластер Proxmox','◈'],k8s_node:['Узел Kubernetes','⎈'],pod:['Pod','⬢'],k8s_container:['Контейнер Pod','◇'],switch:['Коммутатор','⇄'],bridge:['Виртуальный мост','⇄'],router:['Маршрутизатор','⇆'],firewall:['Фаервол','⬢'],client:['Клиент','▱'],dhcp:['DHCP-сервер','D'],dns:['DNS-сервер','N']};
export const CHILDREN={root:['rack','switch','router','firewall','client','dhcp','dns'],rack:['server','switch','router','firewall'],server:['proxmox','ubuntu','debian','windows'],proxmox:['vm','bridge'],vm:['ubuntu','debian','windows'],ubuntu:['docker','bridge','dns','dhcp'],debian:['docker','bridge','dns','dhcp'],windows:['docker','bridge','dns','dhcp'],docker:['container','bridge']};
CHILDREN.root.push('k8s_cluster','proxmox_cluster');for(const os of ['ubuntu','debian','windows'])CHILDREN[os].push('application','k8s_node','containerd','kubelet');CHILDREN.proxmox.push('application');CHILDREN.k8s_cluster=['k8s_service'];CHILDREN.container=['application'];CHILDREN.k8s_node=['pod','kubelet','containerd'];CHILDREN.pod=['k8s_container'];CHILDREN.k8s_container=['application'];
Object.assign(TYPES,{media_converter:['Медиаконвертер RJ45 ↔ SFP','⇋'],moca_adapter:['MoCA Ethernet ↔ коаксиал','≋'],coax_repeater:['Повторитель BNC 10BASE2','↔'],hub:['Ethernet-концентратор','⋈'],patch_panel:['Медная патч-панель','▦'],fiber_panel:['Оптическая панель ODF','▦']});
 CHILDREN.root.push('media_converter','moca_adapter','coax_repeater','hub','patch_panel','fiber_panel');CHILDREN.rack.push('media_converter','moca_adapter','coax_repeater','hub','patch_panel','fiber_panel');
 export const bridgeTypes=['switch','bridge',...TRANSPARENT];
export const osTypes=['ubuntu','debian','windows'];
export const uid=()=>globalThis.crypto.randomUUID();
export function node(type,parent=null,x=40,y=60){return{id:uid(),type,parent,x,y,w:type==='rack'?650:bridgeTypes.includes(type)?250:260,h:160,name:TYPES[type][0],collapsed:false,interfaces:[],services:{},rules:{blockICMP:false,blockedPorts:[]}}}
export function iface(n,context={}){const defaults=interfaceDefaults(n,context),p={id:uid(),switchMode:'access',accessVlan:1,nativeVlan:1,allowedVlans:[1,10,20],ip:'',prefix:24,gateway:'',dns:'',mode:'auto',...defaults};n.interfaces.push(p);return p}
export function create(type,parent,x,y,context={}){const n=node(type,parent,x,y);const count=type==='bridge'?1:['media_converter','moca_adapter','coax_repeater'].includes(type)?2:['patch_panel','fiber_panel','hub'].includes(type)?4:bridgeTypes.includes(type)?6:['router','firewall'].includes(type)?2:['rack','proxmox','vm','docker','application','k8s_node','k8s_cluster','proxmox_cluster','k8s_container','k8s_service','containerd','kubelet'].includes(type)?0:1;for(let i=0;i<count;i++)iface(n,context);if(TRANSPARENT.includes(type)){n.interfaces=n.interfaces.slice(0,['media_converter','moca_adapter','coax_repeater'].includes(type)?2:4);n.interfaces.forEach(p=>p.kind='physical');if(type==='media_converter')n.interfaces[1].profile='sfp_lx';if(type==='moca_adapter')n.interfaces[1].profile='moca';if(type==='coax_repeater')n.interfaces.forEach(p=>p.profile='bnc');if(type==='patch_panel')n.interfaces.forEach(p=>p.profile='passive_rj45');if(type==='fiber_panel')n.interfaces.forEach(p=>p.profile='passive_smf')}if(type==='bridge')n.members=[];if(type==='dhcp')n.services.dhcp={cidr:'10.10.0.0/24',start:100,end:200,gateway:'10.10.0.1',dns:'10.10.0.53',enabled:true};if(type==='dns')n.services.dns={enabled:true,records:{'site.lab':'10.10.0.10'}};if(type==='container'){n.applicationModel=true;n.services.http={port:80,publishHost:'',publishPort:8080}}if(['container','k8s_container'].includes(type))n.services.runtime={image:'alpine:latest',status:'running',restart:'unless-stopped',command:'',environment:'',volumes:'',cpu:'1',memory:'256MiB',network:type==='container'?'bridge':'pod'};if(type==='application'){n.services.http={port:80,enabled:true};n.services.process={command:''}}if(type==='k8s_node')n.services.kubernetes={role:'worker',runtime:'containerd',version:'',cni:'',podCIDR:''};if(type==='containerd')n.services.daemon={endpoint:'unix:///run/containerd/containerd.sock',namespace:'k8s.io',version:''};if(type==='kubelet')n.services.agent={runtimeId:'',version:''};if(type==='k8s_service')n.services.nodeport={namespace:'default',selector:'app=nginx',port:80,targetPort:80,nodePort:30080,externalTrafficPolicy:'Local'};if(type==='pod')n.services.pod={namespace:'default',status:'running',labels:''};return n}
export function empty(){return{version:1,schemaVersion:2,nodes:[],links:[],subnets:[]}}
export const ipnum=s=>{if(typeof s!=='string'||!/^\d+\.\d+\.\d+\.\d+$/.test(s))return null;const a=s.split('.').map(Number);return a.every(x=>x>=0&&x<=255)?a.reduce((n,x)=>(n*256+x)>>>0,0):null};
export const ipstr=n=>[24,16,8,0].map(s=>(n>>>s)&255).join('.');
export function range(cidr){const [ip,p]=cidr.split('/'),n=ipnum(ip),prefix=Number(p);if(n===null||!Number.isInteger(prefix)||prefix<1||prefix>30)return null;const size=2**(32-prefix),base=Math.floor(n/size)*size;return{base,last:base+size-1,prefix,size}}
export function segments(s){return networkGraph(s).segments}
export function diagnostics(s){const issues=[];for(const g of segments(s)){const ips=new Map();for(const p of g){if(!p.ip)continue;const r=range(`${p.ip}/${p.prefix}`),n=ipnum(p.ip);if(!r||n===r.base||n===r.last)issues.push(`${p.node.name}/${p.name}: недопустимый адрес ${p.ip}/${p.prefix}`);if(ips.has(p.ip))issues.push(`Конфликт IP ${p.ip}: ${ips.get(p.ip)} и ${p.node.name}`);ips.set(p.ip,p.node.name);if(p.gateway&&(!r||ipnum(p.gateway)===null||ipnum(p.gateway)<=r.base||ipnum(p.gateway)>=r.last))issues.push(`${p.node.name}: шлюз вне подсети`)}const dh=g.filter(p=>p.node.services.dhcp?.enabled);if(dh.length>1)issues.push('В сегменте несколько DHCP-серверов') }issues.push(...physicalIssues(s),...workloadIssues(s));return issues}
export function allocate(s,planner=false){const notes=[];s.subnets=[];const groups=segments(s);const reserved=groups.flatMap(g=>g.filter(p=>p.ip).map(p=>range(`${p.ip}/${p.prefix}`))).filter(Boolean);let next=1;for(const g of groups){const endpoints=g.filter(p=>!bridgeTypes.includes(p.node.type));if(!endpoints.length)continue;const dh=g.filter(p=>p.node.services.dhcp?.enabled);if(dh.length>1){notes.push('Отказ: несколько DHCP в сегменте');continue}let cfg=dh[0]?.node.services.dhcp;let r=cfg?range(cfg.cidr):null;if(cfg&&(!r||!Number.isInteger(cfg.start)||!Number.isInteger(cfg.end)||cfg.start<1||cfg.end>=r.size-1||cfg.start>cfg.end)){notes.push('Отказ: некорректный пул DHCP');continue}if(!cfg&&!planner){notes.push('Нет DHCP: адреса сегмента не выданы');continue}if(!r){r=endpoints.map(p=>p.ip&&range(`${p.ip}/${p.prefix}`)).find(Boolean);if(!r){do{r=range(`10.42.${next++}.0/24`)}while(reserved.some(a=>r.base<=a.last&&a.base<=r.last));reserved.push(r)}}const used=new Set(g.filter(p=>p.ip&&p.mode==='manual').map(p=>ipnum(p.ip)));for(const a of [cfg?.gateway,cfg?.dns])if(a)used.add(ipnum(a));let host=cfg?cfg.start:10;for(const p of endpoints){if(p.mode==='manual')continue;while(used.has(r.base+host))host++;if(host>(cfg?cfg.end:r.size-2)){notes.push('Пул адресов исчерпан');break}const original=p.node.interfaces.find(a=>a.id===p.id);Object.assign(original,{ip:ipstr(r.base+host),prefix:r.prefix,gateway:cfg?.gateway||'',dns:cfg?.dns||''});used.add(r.base+host++);}s.subnets.push({cidr:`${ipstr(r.base)}/${r.prefix}`,source:cfg?'DHCP':'Планировщик',ports:g.map(p=>p.id)});notes.push(`${cfg?'DHCP':'Планировщик'}: ${ipstr(r.base)}/${r.prefix}`)}return notes}
