export function connect(s,a,b,options={}){const all=s.nodes.flatMap(n=>n.interfaces),p=all.find(p=>p.id===a),q=all.find(p=>p.id===b);if(!p||!q||a===b)throw Error('Выберите два разных контакта');if(s.links.some(l=>[l.a,l.b].includes(a)||[l.a,l.b].includes(b)))throw Error('Контакт уже занят. Сначала удалите кабель.');const link={id:uid(),a,b,...options};if(!link.medium)link.medium=linkMedium(p,q);if(link.medium==='model'&&p.profile&&q.profile)throw Error('Разные среды портов: выберите совместимые модули или медиаконвертер');const error=physicalError(p,q,link);if(error)throw Error(error);s.links.push(link)}
const validId=id=>typeof id==='string'&&/^[A-Za-z0-9_.:-]{1,256}$/.test(id);
export function validate(s){if(!s||s.version!==1||!Array.isArray(s.nodes)||!Array.isArray(s.links)||s.nodes.length>400||s.links.length>2000)throw Error('Некорректный формат схемы (версия 1, до 400 нод)');validateWireRoutes(s.wireRoutes);const ids=new Set(),ports=new Set();for(const n of s.nodes){if(!TYPES[n.type]||!validId(n.id)||ids.has(n.id)||typeof n.name!=='string'||!Array.isArray(n.interfaces)||!Number.isFinite(n.x)||!Number.isFinite(n.y)||n.x<0||n.y<0||n.x>10000||n.y>10000)throw Error('Некорректная нода');ids.add(n.id);ensurePassivePairs(n);if(n.interfaces.length>32)throw Error('Слишком много интерфейсов');for(const p of n.interfaces){if(!validId(p.id)||ports.has(p.id)||typeof p.name!=='string'||typeof p.ip!=='string'||typeof p.gateway!=='string'||typeof p.dns!=='string'||!['auto','manual'].includes(p.mode)||!Number.isInteger(p.prefix)||p.prefix<1||p.prefix>30)throw Error('Некорректный интерфейс');if(p.kind===undefined)p.kind=['server','switch','router','firewall','client','rack'].includes(n.type)?'physical':'virtual';if(!['physical','virtual'].includes(p.kind))throw Error('Неизвестный тип интерфейса');if(p.profile&&!PROFILES[p.profile])throw Error('Неизвестный профиль интерфейса');if(p.profile)p.kind=p.profile==='virtual'?'virtual':'physical';if(p.switchMode&&!['access','trunk'].includes(p.switchMode))throw Error('Неизвестный режим порта');for(const v of [p.accessVlan,p.nativeVlan,p.vlanId,...(p.allowedVlans||[])].filter(v=>v!==undefined)){if(!Number.isInteger(v)||v<1||v>4094)throw Error('VLAN вне диапазона 1–4094')}if((p.allowedVlans||[]).length>128)throw Error('Слишком много VLAN');if(p.lagGroup&&(!['string'].includes(typeof p.lagGroup)||p.lagGroup.length>32))throw Error('Неверное имя LAG');if(p.lagMode&&!['static','active','passive','backup'].includes(p.lagMode))throw Error('Неверный режим LAG');ports.add(p.id)}n.services??={};n.rules??={blockICMP:false,blockedPorts:[]};if(!Array.isArray(n.rules.blockedPorts))throw Error('Некорректные правила');if(n.services.dns&&(!n.services.dns.records||typeof n.services.dns.records!=='object'))throw Error('Некорректный DNS');}for(const n of s.nodes){let cur=n;const seen=new Set();while(cur.parent){if(seen.has(cur.id))throw Error('Цикл вложенности');seen.add(cur.id);const p=s.nodes.find(a=>a.id===cur.parent);if(!p||!CHILDREN[p.type]?.includes(cur.type))throw Error('Недопустимая вложенность');cur=p}}const busy=new Set(),linkIds=new Set();for(const l of s.links){if(!validId(l.id)||linkIds.has(l.id)||(l.medium!==undefined&&!Object.hasOwn(MEDIA,l.medium))||!ports.has(l.a)||!ports.has(l.b)||l.a===l.b||busy.has(l.a)||busy.has(l.b))throw Error('Некорректный кабель');linkIds.add(l.id);busy.add(l.a);busy.add(l.b)}migrateDocker(s,create);upgradeDockerPath(s);migrateApplications(s);provisionControl(s,create);validateWorkloads(s);validateControl(s);if(s.nodes.length>400)throw Error('После обновления модели больше 400 нод');const assigned=new Set();for(const n of s.nodes.filter(n=>n.type==='bridge')){n.members??=[];if(!Array.isArray(n.members))throw Error('Некорректные участники моста');const allowed=new Set(bridgeCandidates(s,n).map(a=>a.p.id));for(const id of n.members){if(!allowed.has(id)||assigned.has(id))throw Error('Интерфейс вне области хоста или уже состоит в другом мосту');assigned.add(id)}}return s}
